package dev.zomboid.remains;import fixture.*;import java.util.*;public class ProfileCompat{public static int calls;public static void corpse(Object c,Object w,Object e){calls++;try{Object inv=c.getClass().getField("inventory").get(c);inv.getClass().getMethod("clearContent").invoke(inv);@SuppressWarnings("unchecked")List<Object>list=(List<Object>)c.getClass().getField("generated").get(c);for(int i=0;i<list.size();i++)inv.getClass().getMethod("setItem",int.class,Object.class).invoke(inv,i,list.get(i));}catch(Exception x){throw new RuntimeException(x);}}}